class Solution {
    public long putMarbles(int[] weights,int k){
        int[] boundaries=new int[weights.length-1];
        for(int i=0;i+1<weights.length;i++)boundaries[i]=weights[i]+weights[i+1];
        Arrays.sort(boundaries);
        long answer=0;
        for(int i=0;i<k-1;i++)answer+=(long)boundaries[boundaries.length-1-i]-boundaries[i];
        return answer;
    }
}

code.kotlin:
class Solution {
    fun putMarbles(weights:IntArray,k:Int):Long{
        val boundaries=IntArray(weights.size-1){
            weights[it]+weights[it+1]
        };
        boundaries.sort();
        var answer=0L;
        for(i in 0 until k-1)answer+=boundaries[boundaries.lastIndex-i].toLong()-boundaries[i];
        return answer
    }
}

